import json, pathlib, os
root=pathlib.Path('/workspace/omega_runtime')
current=root/'current'
state=root/'state'
out={'current_exists':current.exists(),'current_resolved':str(current.resolve()) if current.exists() else None,'cpu_count':os.cpu_count()}
for name in ['SUPERVISOR_STATUS.json','STATUS.json','ASSEMBLY_STATUS.json','cortex_state/STATE.json','brain/STATUS.json']:
 p=state/name
 out[name]={'exists':p.exists()}
 if p.exists():
  try: out[name]['json']=json.loads(p.read_text())
  except Exception as e: out[name]['error']=type(e).__name__
for p in ['/sys/fs/cgroup/cpu.max','/sys/fs/cgroup/cpuset.cpus.effective']:
 q=pathlib.Path(p)
 out[p]=q.read_text().strip() if q.exists() else None
print(json.dumps(out,sort_keys=True))
